def xor_triangle_count(n):
    if n <= 1:
        return 0
    if n % 2 == 1:
        return n
    half = n // 2
    count = 0
    for i in range(1, half+1):
        if i % 2 == 1:
            if gcd(i, n-i) > 1:
                count += 2
                break
        else:
            if gcd(i, n-i) == 1:
                count += 2
                break
    odd_count = 0
    for i in range(1, n):
        if gcd(i, n-i) == 1:
            odd_count += 1
            if (i + n - i) % 2 == 0:
                count += odd_count - 1
                if i % 2 == 1:
                    count += odd_count - (i // 2)
                    if (i + n // 2) % 2 == 0:
                        count += odd_count - (n // 2 - i // 2)
                else:
                    count += n // 2
                    if (i + n // 2) % 2 == 0:
                        count += (n // 2 - i // 2)
    return count

