    def calc(k, x):
        if x == k - 1:
            return 2
        if x == k:
            return 2
        if k <= x:
            return 1
        if k == 2 * x:
            return 2

        if (k - k // (x + 1) + 1) ** 2:
            return (3 * (k // (x + 1)) ** 3) % MOD
        else:
            return ((k // (x + 1)) ** 2) * (3 * (x + 1)) ** 2 % MOD

