from functools import cache

def count_permutations(n, a, b, mod=998244353):
    if a + b != n:
        return 0

    @cache
    def dp(index, carry, takeweight):
        if index >= n:
            return 1 if carry == 0 else 0
        if takeweight > carry:
            return 0
        if not takeweight and not carry:
            return 0
        with_index = dp(index + 1, carry + 1, takeweight)
        max_weight_of_index = n + 1 if index == 0 else max(takeweight, weight[index - 1])
        not_with_index = dp(index + 1, carry, max_weight_of_index)
        return (with_index + not_with_index) % mod

    weight = list(range(n))
    return dp(1, 0, 1) - (1 if n else 0)  # Adjusting for leading bag treatment

