def find_permutation(n, k):
    # If k equals n(n+1)/2, check if n=1
    if k == n * (n + 1) // 2:
        return "YES\n" + "1"

    # If k > n(n+1)/2, calculate the number of permutations with this beauty
    n_minus_one = n - 1
    if k > n_minus_one * (n - 1 + n_minus_one) // 2:
        return "NO"

    # Find numbers p1, p2,..., pn-1 such that number of pairs is less than 4
    p = list(range(1, n))
    segments = []
    for i in range(1, n):
        for j in range(i):
            test_p = p[j:j+i]
            segments.append([test_p, "YES"])
    for i in range(1, n):
        for j in range(i):
            test_p = p[j:i+j] + [p[i]]
            if "YES" in segments and segments[segments.index("YES")][0][0] == test_p:
                segments.remove(segments[segments.index("YES")])
                segments.append([test_p, "NO"])
    if len(segments) < 4:
        return "NO"
    return "YES\n" + "".join([str(i) for i in p]).replace(" ", "") + "".join(["\nNO" for _ in range(2)]) + "".join([k[1] for k in segments]) + "\n" + "".join(["\nYES\n\n".replace(" ", "") for k in segments].split("NO")[:3])
