        elif deliveries and l - deliveries[-1] == free_water:
            res = b_c0 + max(0, deliveries[-1] + 1) * b - b_c0 + b * deliveries[-1]
        else:
            res = b_c0
        deliveries.insert(bisect.bisect_left(deliveries, t), t)
