        for distance in range(i): # includes i
            valid_stops = set()
            previous_groups = previous_distances_map[i - 1]
            for stop in previous_groups[distance]:
                valid_stops.add(stop - distance)
                valid_stops.add(stop + distance)
            previous_distances_map[i][distance] = sorted(valid_stops)

    results = []
    previous_group = 0
    count = 0
    previous_stops = set()
    for distance in range(n):
        while count < len(distances_map[0][distance]):
            stop = distances_map[0][distance][count]
            if stop not in previous_stops:
                interval = (stop - distance, distance)
                results.extend(previous_distances_map[previous_group][interval[0]])
                for same_distance_stops in previous_distances_map[previous_group][interval[1]]:
                    if len(distances_map[previous_group][interval[1]][stop - 1]):
                        results.extend(set(distances_map[previous_group][interval[1]][max(stop, distance) + 1: -1]) - set(distances_map[previous_group][interval[1]][same_distance_stops - 1]))
            count += 1

        previous_stops.update(distances_map[0][distance])
        if previous_group > 0:
            previous_group -= 1
        else:
            previous_group = len(distances_map[0])
            results.extend(count - 1)

    previous_group = 0
    count = 0
    while count < len(distances_map[0]):
        stop = distances_map[0][count]
        results.extend(previous_distances_map[previous_group][0])
