import math

def count_numerically_stable_numbers(N, K):
    """
    Count the number of integers between 0 and N (inclusive) such that the product of its digits is greater than or equal to K!.
    """
    if K == 1:
        return sum(1 for num in range(1, N + 1) if num >= math.factorial(N))
    else:
        return sum(num in product for num in range(N + 1) for product in product_range(N, K + 1))

def product_range(start, length):
    """
    Generate the product of digits for numbers ranging from start to start * 10^(length-1).
    """
    return (num // (10 ** (length - 1)) for num in range(start, start * 10 ** length))

