                    containers.append(m[(i, True)])
                if not (i > t, False) in m or i - 1 == t:
                    containers.append(m[(i > t, False)])
        total = 2*m - t
        avg_transfer = total//2
        remainder = total % 2
        if not remainder or c[avg_transfer]:
