MOD = 998244353
from collections import Counter

def nCr(n, r):
    ans = 1
    r = min(n - r, r)
    for i in range(r):
        ans *= n - i
        ans %= MOD
        n -= i
        ans *= powmod(i + 1, MOD - 2, MOD)
        ans %= MOD
    return ans

def powmod(x, y, z):
    ans = 1
    x %= z
    while y:
        if y & 1:
            ans = ans * x % z
        y >>= 1
        x = x * x % z
    return ans

def solve(n, a, b):
    if n < a or n < b:
        return 0
    if a + b == 0:
        return 1
    if a + b == n:
        return powmod(nCr(n, b), powmod(2, n - b - a, MOD), MOD)
    way1 = powmod(nCr(n - 1, a - 1) * powmod(2, b - a + 1, MOD), powmod(2, MOD - 2, MOD), MOD)
    way2 = powmod(nCr(n - 1, b - 1) * powmod(2, a - b + 1, MOD), powmod(2, MOD - 2, MOD), MOD)
    if a * b > 0:
        return powmod(nCr(n, b - 1), powmod(2, b - b + a - 1, MOD), MOD) * powmod(2 * b, powmod(b - b + a, MOD - 2, MOD), MOD) % MOD
    return (powmod(nCr(n - 1, a - 1) * powmod(2, b - a * 2, MOD), powmod(2, MOD - 2, MOD), MOD) + powmod(nCr(n - 1, b - 1), powmod(2, b - b, MOD), MOD)) % MOD

