from heapq import heappush, heappop

def findSeconds(n, levels):
    closestNext = [0] * len(levels)
    h, unused = [], []
    dist = [float('inf')] * len(levels)
    dist[0] = 0
    heappush(h, (0, 0))
    prev_dist = dist[:]

    for i in range(1, len(levels)):
        minv, index = heappop(h)
        if index != 0 and dist[index - 1] > minv:
            heappush(h, (dist[index - 1], index - 1))
            prev_dist[index - 1] = minv
        elif index != n - 1 and dist[index + 1] > minv:
            heappush(h, (dist[index + 1], index + 1))
            prev_dist[index + 1] = minv

        for i in range(n):
            if levels[index] == i:
                closestNext[i] = min(max(n - 1, closestNext[index - 1] - 1), min(dist[index], i - 1 - dist[index]))

                if levels[index] == n - 1 and prev_dist[n-1] != float('inf'):
                    closestNext[index] = 2*i - prev_dist[n - 1] + 1

                continue
            hqe = i + levels[index]
            if hqe == n:
                hqe %= n
            if hqe < n and dist[hqe] > hqe:
                heappush(h, (dist[hqe] = i + levels[index]))
            elif hqe >= n and dist[hqe - n] > 0 and dist[hqe] > hqe - n + i:
                heappush(h, (dist[hqe] = hqe - n + i))
            elif 0 < hqe + dist[hqe] < closeNext[index] and dist[hqe - i * dist[hqe]] > 0 and dist[hqe] + closestNext[index] - hqe + i * dist[hqe] < min(dist[hqe - i * dist[hqe]], closestNext[index]):
                heappush(prev_dist, (i + levels[index], hqe - i * dist[hqe]))
                heappush(prev_dist, (hqe + dist[hqe], hqe + i * dist[hqe + dist[hqe]]))

    print(*closestNext)

