import math

def binary_search(solutions, player_id):
    lower = 0
    upper = len(solutions) - 1

    while lower <= upper:
        mid = math.floor((lower + upper) / 2)
        if solutions[mid] > player_id:
            upper = mid - 1
        else:
            lower = mid + 1

    return solutions[mid]

def forget(player_id, round_id, solutions):
    global player_count
    new_player_count = player_count
    solutions[player_count] = round_id
    for i in range(player_id):
        if round_id - i > 0 and (round_id - i) < player_count:
            new_player_count -= 1
            solutions[round_id - i - 1] = 1 - player_count + 1
    solutions[0] = new_player_count
    return new_player_count

