def tri(angle):
    return (power(8, angle) - 1) // (2 * power(2, 16))

def pairs_in_a_triangle(a, d, angles):
    # Check if a, b < d and if possible to join with angles
    if a <= d and (angles >= a or angles - d >= a) and angles - a < d:
        return tri(angles - d) - tri(d) - tri(d - a) - tri(a)
    return 0

def combine_two_dict(d1, d2):
    new = d2.copy()
    for k in d1:
        new[d1[k] + d2[k]] = max(d1[k], d2[k]) + d1[k] + d2[k]
        for v in range(d2[k] + 1, d1[k] + d2[k] + 1):
            if k not in new:
                new[k] = v
    return new

def XOR_triplets(nbx, d):  # nbx is the 2^200000 sparse array
    if len(nbx) == 1:  # Base case
        return pairs_in_a_triangle(nbx[1], d, nbx[1] + 1)
    dp = nxb
    while len(dp) > 1:
        dp = combine_two_dict(dp, dp)
    newdp = []
    olddp = []
    for k in dp:
        if 0 in olddp:
            olddp.sort()
            olddp.sort(key=k)
        olddp.append(k)
        olddp = newdp
    newdp = []
    for k in dp:
        if len(dp) >= 2 and 0 in olddp:
            olddp.sort()
            olddp.sort(key=k)
        olddp.append(k)
        olddp = newdp
    return dp

def cost(nbx):
    total = 0
    for d in range(2, 200000):
        total = (total + nbx[d] * XOR_triplets(nbx, d)) % 998244353
    return total % 998244353

