from collections import deque, defaultdict

def color(root, parrots):
    colors = defaultdict(int)
    queue = deque([root])
    while queue:
        node = queue.popleft()
        colors[node] = 0
        for neighbor in parrots[node]:
            if neighbor not in parrots:
                queue.append(neighbor)
    return colors

def bfs(n, colors, idx):
    neighbors = defaultdict(list)
    for color, node_set in colors.items():
        for node in node_set:
            for neighbor in reversed(parrots[node]):
                if neighbor in colors:
                    neighbors[color].append(colors[neighbor])
                    break
    return max(colors[idx] + 1 + min(nums[color] for color, nums in neighbors.items()), bfs(n, neighbors, idx))

