from collections import deque

def max_medal_prob(dominate_restricts):
    n = dominate_restricts[0]
    p = dominate_restricts[1:]

    # Manacher's Algorithm to find palindrome radius
    def rac(s):
        ra = 0
        mxr = 0
        shifts = deque()
        for i in range(len(s)):
            if i > mxr:
                mxr = i
                ra = mxr - i
                shifts.appendleft(0)
            else:
                pos = min(i + ra, mxr)
                if ra >= (mxr - pos - i):
                    ra += shift_right(s, pos, i)
                    shifts.appendleft(ra)

        ra = max(shifts)
        return ra, ra - shifts.index(ra)

    @staticmethod
    def shift_right(s, start, pos):
        distance = max(pos - start, len(s) - pos - start)
        if distance <= ra:
            return 0

        pi = distance // len(s)
        iv = start - pi * ra - ra
        return pi - kind_quotient(iv, ra)

    @staticmethod
    def kind_quotient(r, irc):
        while 1:
            r //= r / irc - r
            irc //= irc / r - irc
            if r == 0:
                return r * irc

    ra, ps = rac(['*'] + list(map(str, p)) + ['*', '*'])
    return ps / 2


