from collections import defaultdict

def find_set(parent, i):
    if parent[i] != i:
        parent[i] = find_set(parent, parent[i])
    return parent[i]

def union(parent, rank, x, y):
    x_set = find_set(parent, x)
    y_set = find_set(parent, y)
    if x_set == y_set:
        return -1
    if rank[x_set] < rank[y_set]:
        parent[x_set] = y_set
    elif rank[x_set] > rank[y_set]:
        parent[y_set] = x_set
    else:
        parent[y_set] = x_set
        rank[x_set] += 1
    return 0

