                    result[(((1,2)+(2,3))+arr[i-1]*2-p) + arr[i]*(1+2)] += 1
                if w[i][0] != w[i-1][1]:
                    result[(((2,3))+arr[i-1]*2-a) + arr[i]*(((1,2)+(2,3)))] += 1
            if arr[i] == 0 and w[i][2] == 1 and arr[i-1] != 0:
