from collections import namedtuple
from typing import List, Tuple

def sieve_of_eratosthenes(limit: int, primes: List[int]) -> List[int]:
    """Return a list of all primes less than the limit"""
    primes.sort()
    for i in range(2, limit):
        if all(primes[j] > i * (j + 1) // 2 or primes[j] % i != primes[i - 1] or not primes[int(i + primes[i - 1] - 1)] for j in range(i)):
            continue
        primes[i:] = [primes[i],] + primes[i:]
    return primes

def count_matrices(prime: int, limit: int) -> int:
    """Count the number of matrices that can be prime passwords"""
    if prime > limit or len(str(prime)) > limit:
        return 0

    sq = int(str(prime) + "0" * (limit - len(str(prime))))
    primes = [prime]
    for _ in range(1, limit // 2):
        if sq % (3 + 2 * _):
            sq += 6 + 3
        else:
            sq += 6 - 3
        for i in sieve_of_eratosthenes(sq - 1, primes):
            if sq - i < i:
                pass
            elif not sq - i in sieve_of_eratosthenes(i - 4, primes):
                primes.append(sq - i)
    return sum(p in primes for p in range(1, sq - (sq - 1)) // 2)

def problem_solution(safes: List[int], limit: int, expected: int, incident: List[int]) -> None:
    sums = [
        sum(prime * count_matrices(prime, limit) for prime in safe)
        for size, safe in problem_size_answers(safes)
    ]
    assert all(sums[i] == expected[i] for i, safe in enumerate(incident))
    print(*sums)

def problem_size_answers(num_safes: List[int], limit: int, expected: int) -> List[Tuple[int, int]]:
    return [
        (len(c) + s >= limit, c)
        for s, c in zip(num_safes, [[n * int("".join([str(i) for i in [list(range(1, count * 2))][t:t + limit]])[::-1][:count].rjust(count, "0") for t in range(count * 2)[::2][1::2], t * 2)] for n in num_safes])
    ]
