MOD = 10 ** 9 + 7

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def count_valid_permutations(n, gaps, fixed_numbers):
    product = 1
    prime_factors = [0] * (n + 1)

    for i in range(2, n + 1):
        if not fixed_numbers[i]:
            for j in range(i, n + 1, i):
                gcd_result = gcd(fixed_numbers[j], i)
                if gcd_result == 1:
                    product = (product * (fixed_numbers[j] - 1)) % MOD
                product = (product * (fixed_numbers[j] // gcd_result)) % MOD

    for gap in gaps:
        product = (product * prime_factors[gap]) % MOD
        prime_factors[gap] = 1

    total_permutations = pow(n, product - 1, MOD)
    return total_permutations * len(gaps) % MOD

